#!/usr/bin/php
<?php
declare(strict_types=1);$t=json_decode((string)file_get_contents($argv[1]??''),true,32,JSON_THROW_ON_ERROR);$enabled=(bool)($t['enabled']??false);$port=(int)($t['port']??0);$app=(string)($t['application']??'');$key=(string)($t['publish_key']??'');if($port<1024||$port>65535||!preg_match('/^ingest_[a-f0-9]{16}$/',$app)||!preg_match('/^[a-f0-9]{48}$/',$key))throw new RuntimeException('Configuración RTMP inválida.');$ips=[];foreach($t['allowed_ips']??[] as $ip){if(!filter_var($ip,FILTER_VALIDATE_IP)||in_array($ip,['0.0.0.0','::'],true))throw new RuntimeException('IP RTMP inválida.');$ips[$ip]=true;}if($enabled&&!$ips)throw new RuntimeException('RTMP no puede habilitarse sin IP autorizada.');$path='/etc/nginx/orionx-rtmp.conf';$before=is_file($path)?(string)file_get_contents($path):'';$application=$app.'_'.$key;$allows='';foreach(array_keys($ips) as $ip)$allows.="            allow publish {$ip};\n";$content=$enabled?"rtmp {\n    server {\n        listen {$port};\n        chunk_size 4096;\n        application {$application} {\n            live on;\n            record off;\n{$allows}            deny publish all;\n            allow play 127.0.0.1;\n            allow play ::1;\n            deny play all;\n        }\n    }\n}\n":"# OrionX RTMP deshabilitado\n";if(file_put_contents($path,$content,LOCK_EX)===false)throw new RuntimeException('No se pudo escribir configuración RTMP.');chmod($path,0640);$p=proc_open(['/usr/sbin/nginx','-t'],[1=>['pipe','w'],2=>['pipe','w']],$pipes,null,null,['bypass_shell'=>true]);$out='';foreach($pipes as $pipe){$out.=stream_get_contents($pipe);fclose($pipe);}$ok=is_resource($p)&&proc_close($p)===0;if(!$ok){file_put_contents($path,$before,LOCK_EX);throw new RuntimeException('Nginx rechazó RTMP: '.substr($out,0,500));}$p=proc_open(['/usr/bin/systemctl','reload','nginx'],[1=>['pipe','w'],2=>['pipe','w']],$pipes,null,null,['bypass_shell'=>true]);foreach($pipes as $pipe){stream_get_contents($pipe);fclose($pipe);}if(!is_resource($p)||proc_close($p)!==0){file_put_contents($path,$before,LOCK_EX);throw new RuntimeException('No se pudo recargar Nginx.');}echo "RTMP_CONFIG_OK\n";
